"""Wave 3 epic specs, group D2: QA bug-bash epics (184-199). All use the "qa" convention."""

# ── shared locked rules for every D2 epic (appended after the QA convention) ─────────────────────

def _tools_rules(area, siblings, known):
    out = (
        "- **QA harness rules (`tools/qa/*`).** Import code exactly like `tools/security/support.ts` does: relative paths to "
        "`../../../packages/<x>/src/index.ts`, fakes from `../../../packages/core/src/testing/index.ts`, servers from "
        "`../../../apps/server/src/index.ts`. `tools/` is not a Bun workspace and the root `node_modules` holds only Biome, "
        "TypeScript and `@types`, so **never import a bare package name** (`zod`, `hono`, `picomatch`, …): get schemas from "
        "core's index and use `node:*`, `bun` and `bun:test` built-ins. Don't import another package's `src/testing/*` or "
        "internal files (their Wave 3 owners are rewriting them): copy the few helpers you need into your own `support.ts`. "
        "Create `tools/qa/" + area + "/tsconfig.json` as a copy of `tools/load/tsconfig.json` with "
        "`\"extends\": \"../../../tsconfig.base.json\"` and `\"include\": [\"*.ts\"]`. The root `typecheck` loop only covers "
        "`packages/*` and `apps/*`, so the DoD typechecks your folder explicitly.\n"
        "- **Pin contracts, not today's quirks.** " + siblings + " A passing test must assert what the docs, "
        "ARCHITECTURE §6 or a doc's \"Interfaces for future epics\" promise, so it stays green after their fixes land. "
        "Anything wrong today is a `test.todo('BUG …')`. Findings that are **already known** (listed below) are pinned as "
        "`test.todo('BUG <area> (known, <source>): …')`, marked *known* in REPORT.md, and need no new FIX REQUEST.\n"
        "- **Determinism.** `FakeClock` from core, `127.0.0.1` on port `0`, temp dirs named `starling-qa-<area>-*` under "
        "`os.tmpdir()` and removed in `finally`/`afterAll`, no single wait over 50 ms (poll with a bounded `waitFor` "
        "helper instead). Prefer in-process `app.request(...)` and fetch shims over real sockets."
    )
    if known:
        out += "\n- **Known findings in your area (pin, don't rediscover):**\n" + known
    return out


def _web_rules(siblings, known):
    out = (
        "- **QA harness rules (web QA).** Your tests run in the web test process (`cd apps/web && bun test`), where "
        "`src/test-setup.ts` already registers happy-dom. Import features through `src/features/<x>/index.ts`, data "
        "through `src/data/index.ts`, app pieces through `src/app/index.ts` and `src/lib/index.ts`; fakes and factories "
        "from `@starling/core/testing`; Testing Library from `@testing-library/react`. Never import a feature's internal "
        "files or `test-*.ts` helpers: owners are rewriting them in parallel. Reset the zustand store "
        "(`skyActions.reset()` plus `useSky.setState(createInitialState())`) in `beforeEach` and call Testing Library's "
        "`cleanup()` in `afterEach`, because every web test file shares one process. The folder is typechecked by "
        "`bunx tsc --noEmit -p apps/web` (its `include` already covers `src/**`).\n"
        "- **Pin contracts, not today's quirks.** " + siblings + " A passing test must assert what a doc, a handshake "
        "type or a component's documented props promise, so it stays green after their fixes. Anything wrong today is a "
        "`test.todo('BUG …')`. Already-known findings (below) get `test.todo('BUG <area> (known, <source>): …')` and are "
        "marked *known* in REPORT.md.\n"
        "- **Determinism.** Fake timers/clock injection where the API offers it, no wall-clock assertions, no waits over "
        "50 ms, no real network (stub `fetch` and `EventSource` through the factories the code accepts). Don't duplicate "
        "Epic 139 (a11y, `src/__a11y__`) or Epic 141 (perf budgets, `src/__perf__`)."
    )
    if known:
        out += "\n- **Known findings in your area (pin, don't rediscover):**\n" + known
    return out


def _tools_dod(area, n_tests, extra=None):
    d = [
        "`bun test tools/qa/" + area + "` → 0 fail, ≥ " + str(n_tests) + " passing tests, and every confirmed bug present as a `test.todo` (paste the summary line, which shows the todo count).",
        "`bunx tsc --noEmit -p tools/qa/" + area + "` clean, and `bunx biome check tools/qa/" + area + "` clean.",
        "Determinism: `bun test tools/qa/" + area + " && bun test tools/qa/" + area + "` gives identical pass/todo counts both times, and `ls \"$(bun -e 'console.log(require(\"os\").tmpdir())')\" | grep starling-qa-" + area + "` prints nothing afterwards.",
    ]
    if extra:
        d.extend(extra)
    d.append("`tools/qa/" + area + "/REPORT.md` exists with: coverage list, bug table (id, severity, file:line, one-line repro, known/new, owner epic), open questions, and what to test next.")
    return d


def _web_dod(sub, n_tests, extra=None):
    d = [
        "`cd apps/web && bun test src/__qa__/" + sub + "` → 0 fail, ≥ " + str(n_tests) + " passing tests, every confirmed bug present as a `test.todo` (paste the summary line).",
        "`bunx tsc --noEmit -p apps/web` clean, and `bunx biome check apps/web/src/__qa__/" + sub + "` clean.",
        "Run it twice in one process to prove isolation: `cd apps/web && bun test src/__qa__/" + sub + " src/__qa__/" + sub + "` → identical counts, no \"act(...)\" warnings and no leaked timers.",
    ]
    if extra:
        d.extend(extra)
    d.append("`apps/web/src/__qa__/" + sub + "/REPORT.md` exists with: coverage list, bug table (id, severity, file:line, one-line repro, known/new, owner epic), open questions, and what to test next.")
    return d


